// Cuenta intercambios de la sesion (columna tecnica de soporte,
// no forma parte de los 5 campos de negocio fijos del brief).
const previo = Number($('Preparar Contexto Previo').item.json.memoria_intercambios) || 0;
return [{
  json: {
    ...$json,
    intercambios_actualizados: previo + 1
  }
}];

// Solo se ejecuta cuando se superan los 5 intercambios. Convierte el
// JSON estructurado del Summarizer en un texto breve, y resetea el
// contador a 0 (Paso 8 del brief: sobreescribe, no acumula).
const r = $json.output;
const previo = $('Incrementar Contador de Intercambios').item.json;
const resumenTexto = 'Asunto: ' + r.asunto_principal + ' | Puntos clave: ' + (r.puntos_clave || []).join('; ') + ' | Acción requerida: ' + r.accion_requerida;
return [{
  json: {
    ...previo,
    resumen_para_guardar: resumenTexto,
    intercambios_para_guardar: 0
  }
}];

// Concatena la interacción nueva al resumen existente (texto plano, sin IA).
// Usa referencias por nombre para funcionar tanto si llega desde el IF
// como si llega desde la salida de error del Summarizer.
const base = $('Incrementar Contador de Intercambios').item.json;
const resumenPrevio = $('Preparar Contexto Previo').item.json.memoria_resumen || '';
const nuevoResumen = (resumenPrevio ? resumenPrevio + ' | ' : '') +
  'Consulta: ' + $('📨 Entrada Normalizada').item.json.chatInput + ' → Respuesta: ' + base.output;

return [{
  json: {
    ...base,
    resumen_para_guardar: nuevoResumen,
    intercambios_para_guardar: base.intercambios_actualizados
  }
}];

// Contencion financiera especifica de la rama de voz (Paso 8 del
// checkpoint de Voice AI): no se toca el prompt de Worker_Redaccion
// (afectaria tambien a chat/mail) -- se trunca solo aca, justo antes
// de mandarlo a sintesis de voz.
const texto = ($json.output || '').trim();
const truncado = texto.length > 200 ? texto.slice(0, 197) + '...' : texto;
return [{ json: { ...$json, texto_para_voz: truncado } }];

// Gemini devuelve un JSON anidado, no un campo 'text' plano como Whisper.
// Lo normalizamos a la misma forma que espera el resto del flujo.
const texto = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
return [{ json: { text: texto.trim() } }];

// Convierte el binario del audio a base64 en un paso aparte -- hacerlo
// directo dentro de la expresion del HTTP Request es fragil en n8n
// (el campo terminaba llegando vacio). Este patron es mas confiable.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = buffer.toString('base64');
return [{ json: { ...$json, audio_base64: base64String } }];

// Marco de Compliance y Destruccion Binaria (Paso 12 del brief de
// Voice AI). El audio nunca se escribe a disco ni a ninguna base de
// datos en todo el flujo -- vive solo en la memoria volatil de esta
// ejecucion. Este nodo lo hace explicito: descarta toda referencia
// binaria del item antes de que la ejecucion termine.
const { binary, ...jsonSinBinario } = $input.item;
return [{ json: { ...jsonSinBinario.json, audio_procesado: true, audio_destruido: true } }];

const workerInvocado = $json.worker_invocado || '';
const requiereAprobacion = $json.requiere_aprobacion === true;
const output = $json.output || '';

// Pregunta original del empleado: es texto escrito por el usuario, así que
// se escapa para no romper el HTML, y se acorta si viene con el hilo de mail citado.
function escapar(t) {
  return String(t)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\n/g, '<br>');
}
let pregunta = ($('📨 Entrada Normalizada').item.json.chatInput || '').trim();
if (pregunta.length > 300) pregunta = pregunta.slice(0, 300) + '…';
const preguntaOriginal = escapar(pregunta);

let datos = {};
try { datos = JSON.parse($json.parametros_enviados || '{}'); } catch (e) { datos = {}; }
const data = datos.data || datos;

function estilo(colorHeader, titulo, filas) {
  const filasHtml = filas.map(f => `
    <tr>
      <td style="padding: 10px; font-weight: bold; width: 180px; background-color: #f5f5f5;">${f.label}</td>
      <td style="padding: 10px;">${f.valor}</td>
    </tr>`).join('');
  return `
<div style="font-family: Arial, Helvetica, sans-serif; max-width: 700px; margin: 0 auto; border: 1px solid #e0e0e0; border-radius: 10px; overflow: hidden;">
    <div style="background-color: ${colorHeader}; color: white; padding: 20px;">
        <h1 style="margin: 0;">${titulo}</h1>
    </div>
    <div style="padding: 20px; background-color: #fafafa;">
        <table style="width: 100%; border-collapse: collapse;">${filasHtml}</table>
    </div>
    <div style="background-color: #eeeeee; padding: 12px; text-align: center; font-size: 12px; color: #666;">
        Mensaje generado automáticamente por n8n
    </div>
</div>`;
}

let categoria, html;

if (workerInvocado.includes('Soporte')) {
  categoria = 'ticket';
  html = estilo('#d32f2f', '🚨 Ticket de Soporte Generado', [
    { label: '❓ Pregunta', valor: preguntaOriginal },
    { label: '📂 Categoría', valor: 'Soporte Técnico' },
    { label: '🔢 Nro. de Ticket', valor: data.ticket_ID || '-' },
    { label: '📝 Descripción', valor: data.descripcion || '-' },
    { label: '⚠️ Estado', valor: 'Abierto' },
    { label: '🔧 Próximo Paso', valor: output },
  ]);
} else if (workerInvocado.includes('RRHH') && requiereAprobacion) {
  categoria = 'solicitud';
  html = estilo('#f57c00', '📋 Solicitud Registrada', [
    { label: '❓ Pregunta', valor: preguntaOriginal },
    { label: '📂 Categoría', valor: 'Solicitud de Vacaciones' },
    { label: '🔢 Nro. de Solicitud', valor: data.solicitud_ID || '-' },
    { label: '📅 Días Solicitados', valor: data.dias_solicitados ?? '-' },
    { label: '⏳ Estado', valor: 'Pendiente de Aprobación' },
    { label: '📝 Detalle', valor: output },
  ]);
} else {
  categoria = 'informativa';
  html = estilo('#1565c0', 'ℹ️ Respuesta a tu Consulta', [
    { label: '❓ Pregunta', valor: preguntaOriginal },
    { label: '📂 Categoría', valor: 'Consulta de RRHH' },
    { label: '📝 Respuesta', valor: output },
  ]);
}

return [{ json: { ...$json, categoria_email: categoria, html_body: html } }];
